-- Ranking pagination uses score/time/ID; chronological pagination uses time/ID.
drop function get_feed(text,text,text,timestamptz,uuid);
create function get_feed(mode text default 'Following',style text default 'Latest',lang text default 'en',before_time timestamptz default null,before_id uuid default null,before_score numeric default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb;begin
 if mode not in('Following','Topics','Local','Explore','Suggested')or style not in('Latest','Balanced','Most helpful')then raise exception 'Invalid feed selection';end if;
 if mode='Suggested' and minor_account(auth.uid())then raise exception 'Suggested feed is disabled for minors';end if;
 with eligible as(select p.*,u.handle,u.display_name,u.verified_student,u.account_kind,u.reputation,
 case when mode='Following' then greatest(p.created_at,coalesce((select max(r.created_at)from reposts r join follows f on f.followee_id=r.user_id where r.post_id=p.id and f.follower_id=auth.uid()),p.created_at))else p.created_at end feed_time,
 case when mode='Suggested' and style<>'Latest' then(select count(*)from notes n where n.post_id=p.id and n.published)*3+private_reach_score(p.id)+(case when style='Balanced' then least(u.reputation,20)/10.0 else 0 end)else 0 end rank_score
 from posts p join profiles u on u.id=p.author_id where p.reply_to is null and not u.suspended and p.language=lang
 and(mode in('Explore','Suggested')or mode='Following' and(p.author_id=auth.uid()or exists(select 1 from follows f where f.follower_id=auth.uid()and f.followee_id=p.author_id)or exists(select 1 from reposts r join follows f on f.followee_id=r.user_id where r.post_id=p.id and f.follower_id=auth.uid()))or mode='Topics' and exists(select 1 from post_topics pt join profile_topics ut on ut.topic_id=pt.topic_id where pt.post_id=p.id and ut.user_id=auth.uid())or mode='Local' and p.city<>'' and p.city=(select city from profiles where id=auth.uid()))
 and not exists(select 1 from mutes m where m.owner_id=auth.uid()and(m.account_id=p.author_id or m.word is not null and strpos(lower(p.body),lower(m.word))>0 or m.topic is not null and exists(select 1 from post_topics pt join topics t on t.id=pt.topic_id where pt.post_id=p.id and t.name=m.topic)))), page as(select * from eligible e where before_time is null or(e.rank_score,e.feed_time,e.id)<(coalesce(before_score,0),before_time,before_id)order by rank_score desc,feed_time desc,id desc limit 25)
 select coalesce(jsonb_agg((to_jsonb(e)-'handle'-'display_name'-'verified_student'-'account_kind'-'reputation')||jsonb_build_object('profiles',jsonb_build_object('handle',e.handle,'display_name',e.display_name,'verified_student',e.verified_student,'account_kind',e.account_kind),'promoted',not minor_account(auth.uid())and exists(select 1 from ads a where a.post_id=e.id and a.status='approved'and a.brand_safe),'reason',case when mode='Suggested'then case style when 'Latest'then 'Recent conversation in your chosen language'when 'Balanced'then 'Account reputation and community context considered'else 'Helpful community context and private feedback considered'end else null end)order by e.rank_score desc,e.feed_time desc,e.id desc),'[]'::jsonb)into result from page e;return result;end $$;
